BEGIN;CREATE EXTENSION IF NOT EXISTS pg_cron;CREATE OR REPLACE FUNCTION public.service_expire_awaiting_response_leads_r60() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_now timestamptz:=clock_timestamp();v_count bigint:=0;v_lock bigint:=hashtextextended('vinsansi:r60:commercial-response-timeout',0);BEGIN PERFORM set_config('statement_timeout','10000',true);PERFORM set_config('lock_timeout','1000',true);IF NOT pg_try_advisory_xact_lock(v_lock) THEN RETURN jsonb_build_object('ok',true,'skipped',true,'reason','already_running');END IF;WITH expired AS (UPDATE public.lead_commercial lc SET commercial_stage='recusado',awaiting_response_since=NULL,response_deadline_at=NULL,lead_commercial_updated_at=v_now WHERE lc.commercial_stage='aguardando_resposta' AND lc.response_deadline_at IS NOT NULL AND lc.response_deadline_at<=v_now RETURNING 1) SELECT count(*) INTO v_count FROM expired;RETURN jsonb_build_object('ok',true,'skipped',false,'expiredCount',v_count,'evaluatedAt',v_now);END $$;REVOKE ALL ON FUNCTION public.service_expire_awaiting_response_leads_r60() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.service_expire_awaiting_response_leads_r60() TO service_role;DO $$ DECLARE j bigint;BEGIN IF to_regclass('cron.job') IS NOT NULL THEN FOR j IN SELECT jobid FROM cron.job WHERE jobname='vinsansi-commercial-awaiting-response-timeout-r60' LOOP PERFORM cron.unschedule(j);END LOOP;END IF;END $$;SELECT cron.schedule('vinsansi-commercial-awaiting-response-timeout-r60','0 3 * * *','SELECT public.service_expire_awaiting_response_leads_r60();');SELECT public.service_expire_awaiting_response_leads_r60() AS initial_expiry_run;COMMIT;
